const payload = $json;

const normalizePhone = (value) => {
  let raw = String(value || '').trim();
  if (raw.includes('@')) raw = raw.split('@')[0];
  if (raw.includes(':')) raw = raw.split(':')[0];
  return raw.replace(/\D/g, '');
};

const isLidJid = (value) => String(value || '').includes('@lid');
const isPhoneJid = (value) => String(value || '').includes('@s.whatsapp.net');
const firstTruthy = (...values) => values.find((value) => value !== undefined && value !== null && String(value).trim() !== '') || '';
const asBool = (value) => value === true || value === 'true' || value === 1 || value === '1';

const body = payload.body || {};
const bodyData = body.data || {};
const data = payload.data || bodyData || {};
const msg = data.message || body.message || {};
const key = firstTruthy(body.key, bodyData.key, data.key, msg.key) || {};

const chatInput = firstTruthy(body.chatInput, body.message?.conversation, bodyData.message?.conversation, msg.body, msg.message?.conversation);
const remoteJid = firstTruthy(body.remoteJid, key.remoteJid, bodyData.key?.remoteJid, data.key?.remoteJid, msg.from);
const instanceName = firstTruthy(body.instanceName, bodyData.instance, data.instance, payload.instance);
const apiKey = firstTruthy(body.apiKey, payload.apiKey);

const senderPn = firstTruthy(body.senderPn, bodyData.senderPn, data.senderPn, key.participantPn, key.senderPn);
const senderLid = firstTruthy(body.senderLid, bodyData.senderLid, data.senderLid, key.participantLid, key.senderLid);
const fromMe = asBool(firstTruthy(body.fromMe, bodyData.fromMe, data.fromMe, key.fromMe, bodyData.key?.fromMe, data.key?.fromMe, msg.key?.fromMe));

let adminJid = firstTruthy(body.adminJid, bodyData.adminJid, data.adminJid);
let targetJid = firstTruthy(body.targetJid, bodyData.targetJid, data.targetJid);
let targetPhone = firstTruthy(body.targetPhone, bodyData.targetPhone, data.targetPhone);
let targetLid = firstTruthy(body.targetLid, bodyData.targetLid, data.targetLid);

if (fromMe) {
  targetJid = targetJid || remoteJid;
  if (!targetPhone && isPhoneJid(targetJid)) targetPhone = normalizePhone(targetJid);
  if (!targetPhone && isLidJid(targetJid) && senderPn) targetPhone = normalizePhone(senderPn);
  if (!targetLid && isLidJid(targetJid)) targetLid = targetJid;
  adminJid = adminJid || firstTruthy(senderPn, key.participant, body.sender, data.sender);
}

let phone;
let senderLidOut = senderLid;

if (fromMe && adminJid && !isLidJid(adminJid)) {
  phone = normalizePhone(adminJid);
} else if (senderPn) {
  phone = normalizePhone(senderPn);
} else {
  const rawJid = remoteJid || msg.from;
  if (rawJid && isLidJid(rawJid)) {
    phone = '';
    senderLidOut = senderLid || rawJid;
  } else {
    phone = normalizePhone(rawJid);
  }
}

const message = String(chatInput || '').trim();
const instance = instanceName || 'default';

const lowerMessage = message.toLowerCase();
const looksLikeTrackpalGeneratedReply =
  lowerMessage.includes('no tienes acceso a la consola') ||
  lowerMessage.includes('access denied, you do not have an active account') ||
  lowerMessage.includes('servicio temporalmente no disponible') ||
  lowerMessage.includes('temporarily unavailable');

if (!fromMe && looksLikeTrackpalGeneratedReply) {
  return [];
}

return [{ json: { phone, message, instance, remoteJid, apiKey, sender_lid: senderLidOut, fromMe, adminJid, targetJid, targetPhone, targetLid, raw: payload } }];

const input = $('Parse input').first().json;
const responseData = $('Console call').first().json;
const noReply = responseData.no_reply || false;
const reply = noReply ? '' : (
  (typeof responseData.reply === 'string' && responseData.reply.trim())
    ? responseData.reply
    : 'Servicio temporalmente no disponible. Intenta nuevamente.'
);
const status = responseData.status || null;
const lookupJobId = responseData.lookup_job_id || null;
const tenantId = responseData.tenant_id || null;
const replyTo = responseData.reply_to || null;
const closeJid = responseData.close_jid || null;
const closeJids = Array.isArray(responseData.close_jids) ? responseData.close_jids : (closeJid ? [closeJid] : []);

return [{ json: { ...input, reply, status, lookup_job_id: lookupJobId, tenant_id: tenantId, reply_to: replyTo, no_reply: noReply, close_jid: closeJid, close_jids: closeJids } }];

const fallback = $('Merge & lookup data').first().json;
const data = { ...fallback, ...$json };
const msg = String(data.message || fallback.message || '').trim().toLowerCase();
const reply = String(data.reply || fallback.reply || '').toLowerCase();

const hasLookupResult = Boolean(data.lookup_job_id);
if (hasLookupResult) {
  return [];
}

const isLogoutReply =
  reply.includes('sesión cerrada') ||
  reply.includes('sesion cerrada') ||
  reply.includes('has cerrado sesión') ||
  reply.includes('has cerrado sesion') ||
  reply.includes('goodbye') ||
  reply.includes('cerrado');
const isClosedStatus = String(data.status || '').toLowerCase() === 'closed';
const isLogoutCommand = msg === '0' || msg === 'salir';
const isLogout = isClosedStatus || (isLogoutCommand && isLogoutReply);

if (!isLogout) {
  return [];
}

const closeJids = Array.isArray(data.close_jids) && data.close_jids.length
  ? data.close_jids
  : [data.close_jid || data.reply_to || data.remoteJid];
const uniqueCloseJids = [...new Set(closeJids.filter(Boolean).map(String))];

return uniqueCloseJids.map((remoteJid) => ({ json: { ...data, close_jid: remoteJid } }));

const poll = $json;
const base = $('Merge & lookup data').first().json;
const seedReply = String(base.reply || '');

const looksEnglish = /searching code|you'll receive|code found|open link|error/i.test(seedReply);

const t = looksEnglish
  ? {
      codeFound: (v) => `✅ *Code found*\n\n📋 *${v}*\n\nThis code is time-sensitive. Use it soon.`,
      urlFound: (v) => `✅ *Link found*\n\n🔗 ${v}\n\nOpen link to continue.`,
      notFound: '❌ *Code not found*\n\nNo access-code emails found in last 5 minutes.\n\nRequest a new code and wait 15 seconds before trying again.',
      failed: '❌ *Error while searching code*\n\nAn error occurred while checking mailbox. Try again later.',
    }
  : {
      codeFound: (v) => `✅ *Código encontrado*\n\n📋 *${v}*\n\nEste código es válido por tiempo limitado. Úsalo pronto.`,
      urlFound: (v) => `✅ *Enlace encontrado*\n\n🔗 ${v}\n\nAbre enlace para continuar.`,
      notFound: '❌ *No se encontró código*\n\nNo hay correos con códigos de acceso en últimos 5 minutos.\n\nSolicita nuevo código y espera 15 segundos antes de intentar de nuevo.',
      failed: '❌ *Error al buscar código*\n\nOcurrió error al buscar código. Intenta de nuevo más tarde.',
    };

let finalMessage;
if (poll.result_type === 'code') {
  finalMessage = t.codeFound(String(poll.result_value || ''));
} else if (poll.result_type === 'url') {
  finalMessage = t.urlFound(String(poll.result_value || ''));
} else if (poll.result_type === 'not_found' || poll.result_type === 'duplicate_suppressed') {
  finalMessage = t.notFound;
} else if (poll.status === 'failed' || poll.status === 'timeout' || poll.error_code) {
  finalMessage = t.failed;
} else {
  finalMessage = t.notFound;
}

return { json: { ...base, ...poll, reply: finalMessage } };

const count = parseInt($json._pollAttempts || '0', 10);
const maxAttempts = 5;
const newCount = count + 1;

if ($json.status === 'completed') {
  return { json: { ...$json, _pollAttempts: newCount, _shouldContinue: false } };
}

if (newCount >= maxAttempts) {
  return { json: { ...$json, _pollAttempts: newCount, _shouldContinue: false, status: 'timeout' } };
}

return { json: { ...$json, _pollAttempts: newCount, _shouldContinue: true } };
